function pm_input(string $label, string $name, string $type = 'text', int $max = 100, bool $required = true): void { ?>
<label class="form-group"><?= e($label) ?><input name="<?= e($name) ?>" type="<?= e($type) ?>" <?= $required ? 'required' : '' ?> <?= $type === 'number' ? 'min="0" max="9999999999.99" step="0.01"' : 'maxlength="' . $max . '"' ?>></label>
<?php }
function pm_select(string $label, string $name, string $source, bool $required = true): void { ?>
<label class="form-group"><?= e($label) ?><select name="<?= e($name) ?>" data-source="<?= e($source) ?>" <?= $required ? 'required' : '' ?>><option value="">Đang tải…</option></select></label>
<?php }
function pm_button(string $text): void { ?><button type="submit" class="btn-primary w-100" disabled><?= e($text) ?></button><?php }
